Sure, I'd be happy to help you with that! Here's a Python program that meets your requirements. This program uses a dictionary to store the tasks and their completion status. The keys of the dictionary are the task names, and the values are booleans indicating whether the task is completed or not.

```python
def add_task(tasks):
    """Add a new task to the list of tasks."""
    task_name = input("Enter the name of the task: ")
    if task_name:
        tasks[task_name] = False
        print(f"Task {task_name} added")

def remove_task(tasks):
    """Remove a task from the list of tasks."""
    task_name = input("Enter the name of the task to remove: ")
    if task_name in tasks:
        del tasks[task_name]
        print(f"Task {task_name} removed")
    else:
        print(f"Task {task_name} not found")

def mark_task_as_completed(tasks):
    """Mark a task as completed."""
    task_name = input("Enter the name of the task to mark as completed: ")
    if task_name in tasks:
        tasks[task_name] = True
        print(f"Task {task_name} marked as completed")
    else:
        print(f"Task {task_name} not found")

def display_tasks(tasks):
    """Display the list of tasks."""
    print("Tasks:")
    for task, completed in tasks.items():
        print(f"- {task} ({'completed' if completed else 'not completed'})")

if __name__ == "__main__":
    tasks = {}

    while True:
        command = input("Enter a command (add, remove, mark, or display): ").lower()

        if command == "add":
            add_task(tasks)
        elif command == "remove":
            remove_task(tasks)
        elif command == "mark":
            mark_task_as_completed(tasks)
        elif command == "display":
            display_tasks(tasks)
        else:
            print("Invalid command. Please try again.")

        more = input("Do you want to perform another action? (yes/no): ").lower()
        if more != "yes":
            break
```

This program allows the user to add, remove, and mark tasks as completed. The user can also display the list of tasks at any time.
